mapper.select:
select create_time as createTime, user_name as userName,count(*) as count
from b_event_tracking_cell_report
where is_delete=0

     and create_time>=#{startTime} and create_time<=#{endTime} 


    and user_name = #{userName}


    order by #{orderField}

        #{descField}


        desc


group by create_time,user_name

    order by create_time desc

limit #{current * size},#{size};

select *
from b_event_tracking_cell_report
where is_delete=0

     and create_time>=#{startTime} and create_time<=#{endTime} 


    and user_name = #{userName}


    and request_param->'$.apiCodes' like cancat('%',#{apiCodes},'%')


    order by #{orderField}

        #{descField}


        desc



    order by create_time desc

limit #{current * size},#{size};
